	os.Setenv("TEST_VALUE", "test")

	var wg sync.WaitGroup
	numGoroutines := 100

	for i := 0; i < numGoroutines; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			var ts TestStruct
			customParsers := map[reflect.Type]env.ParserFunc{}
